mapper.select:
select count(*) from dish_templates t
left join dishes d on d.source_template_id=t.id and d.merchant_id = #{merchantId}
where

select  from dish_templates t
join dish_template_categories c on c.id=t.category_id and c.enabled=1
left join dishes d on d.source_template_id=t.id and d.merchant_id = #{merchantId}
where 
order by c.sort_order,t.sort_order,t.id limit #{offset},#{pageSize}
